with metrics as (select *, row_number() over (partition by status order by amount desc, id) event_seq, count(amount) over (partition by status, order_id order by cast(paid_at as bigint) range between 604800 preceding and current row) amount_count_7d, sum(amount) over (partition by order_id order by amount, id rows between unbounded preceding and current row) cumulative_amount, ntile(3) over (partition by order_id, method order by amount, id) amount_bucket, cume_dist() over (order by amount desc) amount_cume_dist from payments), remaining_keys as (select id from metrics except all select id from payments where method = 'cash'), verified as (select s.* from metrics s inner join remaining_keys k on s.id = k.id), metrics_payments as (select id, order_id, method, amount, paid_at, status, event_seq, amount_count_7d, cumulative_amount, amount_bucket, amount_cume_dist, avg(amount_cume_dist) over (partition by status order by cast(paid_at as bigint) range between 604800 preceding and current row) amount_cume_dist_avg_7d, rank() over (partition by method order by amount_cume_dist) amount_cume_dist_rank, round(amount_count_7d / sum(amount_count_7d) over (partition by method, status), 4) amount_count_7d_share from verified) select *, percent_rank() over (order by amount_cume_dist_rank nulls first) amount_cume_dist_rank_percent_rank, avg(amount_cume_dist_avg_7d) over (partition by order_id order by cast(paid_at as bigint) range between 7776000 preceding and current row) amount_cume_dist_avg_7d_avg_90d from metrics_payments
